// Provided: the help screen of the CLI you build in exercise 18.
const TASK_SPEC = {
  usage: 'task <command> [options]',
  commands: [
    { name: 'add', describe: 'add a task' },
    { name: 'list', describe: 'show open tasks' },
    { name: 'done', describe: 'mark a task done' },
  ],
  options: [
    { flags: '--all', describe: 'include finished tasks' },
    { flags: '-h, --help', describe: 'show this help' },
  ],
};

test('the usage line comes first', () => {
  eq(renderUsage({ usage: 'task <command>' }), 'Usage: task <command>');
});

test('command names are padded into a column', () => {
  const lines = renderUsage(TASK_SPEC).split('\n');
  eq(lines[3], '  add     add a task');
  eq(lines[4], '  list    show open tasks');
});

test('options are measured on their own, not with the commands', () => {
  const lines = renderUsage(TASK_SPEC).split('\n');
  eq(lines[8], '  --all         include finished tasks');
  eq(lines[9], '  -h, --help    show this help');
});

test('an empty or missing list leaves no heading behind', () => {
  eq(renderUsage({ usage: 'x', commands: [], options: [] }), 'Usage: x');
  eq(
    renderUsage({ usage: 'x', options: [{ flags: '-v', describe: 'loud' }] }),
    'Usage: x\n\nOptions:\n  -v    loud'
  );
});

test('an entry without a description has no trailing spaces', () => {
  eq(
    renderUsage({ usage: 'x', commands: [{ name: 'up' }, { name: 'status' }] }),
    'Usage: x\n\nCommands:\n  up\n  status'
  );
});

test('renders the whole help screen', () => {
  eq(
    renderUsage(TASK_SPEC),
    [
      'Usage: task <command> [options]',
      '',
      'Commands:',
      '  add     add a task',
      '  list    show open tasks',
      '  done    mark a task done',
      '',
      'Options:',
      '  --all         include finished tasks',
      '  -h, --help    show this help',
    ].join('\n')
  );
});

// ──────────────────────────── tests ──────────────────────────────────────

test('an empty command line parses to empty everything', () => {
  eq(parseCommand([]), {
    command: null,
    flags: {},
    positionals: [],
    passthrough: [],
  });
});

test('the first bare word is the command, the rest are positionals', () => {
  eq(parseCommand(['add', 'buy', 'milk']), {
    command: 'add',
    flags: {},
    positionals: ['buy', 'milk'],
    passthrough: [],
  });
});

test('reads --key=value and --key value, consuming the value', () => {
  eq(parseCommand(['run', '--out=dist', '--mode', 'fast']), {
    command: 'run',
    flags: { out: 'dist', mode: 'fast' },
    positionals: [],
    passthrough: [],
  });
});

test('a flag with nothing to consume is true', () => {
  eq(parseCommand(['build', '--watch']).flags, { watch: true });
  eq(parseCommand(['build', '--watch', '--quiet']).flags, {
    watch: true,
    quiet: true,
  });
});

test('--no-key is false and a short cluster expands', () => {
  eq(parseCommand(['--no-color']).flags, { color: false });
  eq(parseCommand(['commit', '-am', 'fix']), {
    command: 'commit',
    flags: { a: true, m: true },
    positionals: ['fix'],
    passthrough: [],
  });
});

test('-- hands everything after it over verbatim', () => {
  eq(parseCommand(['run', 'test', '--', '--watch', '-x', '--', 'y']), {
    command: 'run',
    flags: {},
    positionals: ['test'],
    passthrough: ['--watch', '-x', '--', 'y'],
  });
});

test('a repeated flag collects its values into an array', () => {
  eq(parseCommand(['build', '--tag', 'a', '--tag=b', '--tag', 'c']).flags, {
    tag: ['a', 'b', 'c'],
  });
});

test('a declared boolean does not eat the next word', () => {
  eq(parseCommand(['--verbose', 'deploy', 'web']).flags, { verbose: 'deploy' });
  eq(parseCommand(['--verbose', 'deploy', 'web'], { booleans: ['verbose'] }), {
    command: 'deploy',
    flags: { verbose: true },
    positionals: ['web'],
    passthrough: [],
  });
});

