// Provided: a stream that remembers instead of drawing.
function collector() {
  const chunks = [];
  const stream = new Writable({
    write(chunk, encoding, callback) {
      chunks.push(chunk.toString('utf8'));
      callback();
    },
  });
  stream.text = () => chunks.join('');
  stream.frames = () => chunks;
  return stream;
}

