});

test('an unknown style name throws instead of printing garbage', () => {
  throws(() => color('x', 'pink'), 'pink');
});

test('stripAnsi removes every escape sequence', () => {
  eq(stripAnsi(bold(color('hi', 'red'))), 'hi');
