test('siblings use the tee until the last one', () => {
  eq(
    renderTree({ name: 'root', children: [{ name: 'a' }, { name: 'b' }, { name: 'c' }] }),
    ['root', '├── a', '├── b', '└── c'].join('\n')
  );
});

test('descendants of a non-last child keep the spine', () => {
  eq(
    renderTree({
      name: 'root',
      children: [
        { name: 'a', children: [{ name: 'a1' }] },
        { name: 'b' },
      ],
    }),
