  eq(quotePosix('build'), 'build');
  eq(quoteWindows('build'), 'build');
});

test('posix leaves the punctuation a path or a flag is made of', () => {
  eq(quotePosix('src/main.js'), 'src/main.js');
  eq(quotePosix('--out=dist'), '--out=dist');
